    [FunctionalTheory][InlineData("wide")][InlineData("direct")][InlineData("ancestor")][InlineData("collection")][InlineData("collectionAncestor")]
    public async Task GivenCurrentOwnedFolderScope_WhenTrashing_ThenOneRetainedCascadeAndUnchangedHandle(string route)
    {
        using var owner=new ProtectionFixture();using var key=new ProtectionFixture();var s=await ProfileSetup.Create(fixture,owner);var a=await AssociationSetup.Items(fixture,s);var root=await Folder(s,a.Folder.Id);var child=await Folder(s,root.Id);var record=await Record(s,child.Id);
        if(route.StartsWith("collection"))await Members(s,a.Collection,[],[route=="collection"?root.Id:a.Folder.Id]);
        if(route!="wide"){var p=await Profile(s,owner,key,folders:route=="direct"?[root.PublicId]:route=="ancestor"?[a.Folder.PublicId]:[],collections:route.StartsWith("collection")?[a.Collection.PublicId]:[]);s=s with{Verifier=await Selected(s,p.Id)};}
        var result=await Trash(s,root);await Success(s,root,[root,child],[record],result);await using var db=fixture.CreateContext();Assert.False((await db.VaultAccessSessions.SingleAsync(x=>x.HandleVerifier==s.Verifier)).Revoked);Assert.Null((await db.Folders.SingleAsync(x=>x.Id==a.Folder.Id)).DeletedAt);
        Assert.Equal("not_found",(await new FolderReadStore(fixture).ReadAsync(new(s.Actor,s.Verifier,child.PublicId),default)).Error);Assert.Equal("not_found",(await new RecordReadStore(fixture).ReadAsync(new(s.Actor,s.Verifier,record.PublicId),default)).Error);
    }
    [FunctionalFact]
    public async Task GivenDeepCascadeWithOverlappingInactiveLinksAndRecipient_WhenTrashing_ThenSnapshotEveryMemberAndBumpEachActiveExternalParentOnce()
    {
        using var owner=new ProtectionFixture();using var client=new ProtectionFixture();using var key=new ProtectionFixture();using var key2=new ProtectionFixture();var s=await ProfileSetup.Create(fixture,owner);var recipient=await ProfileSetup.Create(fixture,client);var a=await AssociationSetup.Items(fixture,s);var root=await Folder(s,a.Folder.Id);var child=await Folder(s,root.Id);var leaf=await Folder(s,child.Id);var r1=await Record(s,root.Id);var r2=await Record(s,leaf.Id);var p=await Profile(s,owner,key,records:[r1.PublicId,r2.PublicId],folders:[root.PublicId,child.PublicId]);var inactive=await Profile(s,owner,key2,records:[r2.PublicId],folders:[leaf.PublicId]);var b=await AssociationSetup.Items(fixture,s);await Members(s,a.Collection,[r1.Id,r2.Id],[root.Id,leaf.Id]);await Members(s,b.Collection,[r2.Id],[child.Id]);await AssociationSetup.Grant(fixture,s,owner,recipient,client,a.Collection,CollectionGrantAccess.ReadWrite);
        await using(var db=fixture.CreateContext()){await db.Profiles.Where(x=>x.Id==inactive.Id).ExecuteUpdateAsync(x=>x.SetProperty(v=>v.DeletedAt,DateTimeOffset.UtcNow));await db.Collections.Where(x=>x.Id==b.Collection.Id).ExecuteUpdateAsync(x=>x.SetProperty(v=>v.DeletedAt,DateTimeOffset.UtcNow));}
        p=await ProfileRow(p.Id);inactive=await ProfileRow(inactive.Id);var parent=await Row(a.Folder.Id);var other=Bytes(a.Record);var recipientBefore=await Snapshot(recipient);var result=await Trash(s,root);await Success(s,root,[root,child,leaf],[r1,r2],result);
        await using(var db=fixture.CreateContext()){
            var nowP=await db.Profiles.AsNoTracking().SingleAsync(x=>x.Id==p.Id);Assert.Equal(p.Revision+1,nowP.Revision);Assert.True(nowP.ServerSequence>p.ServerSequence);Assert.Equal(p.Envelope,nowP.Envelope);Assert.Equal(p.KeyWrappers,nowP.KeyWrappers);Assert.Equal(p.EditedAt,nowP.EditedAt);Assert.Equal(Bytes(inactive),Bytes(await db.Profiles.AsNoTracking().SingleAsync(x=>x.Id==inactive.Id)));
            var nowC=await db.Collections.AsNoTracking().SingleAsync(x=>x.Id==a.Collection.Id);Assert.Equal(a.Collection.Revision+1,nowC.Revision);Assert.True(nowC.ServerSequence>a.Collection.ServerSequence);Assert.Equal(a.Collection.Envelope,nowC.Envelope);Assert.Equal(a.Collection.KeyEpoch,nowC.KeyEpoch);Assert.Equal(b.Collection.Revision,(await db.Collections.SingleAsync(x=>x.Id==b.Collection.Id)).Revision);
            var nowParent=await db.Folders.AsNoTracking().SingleAsync(x=>x.Id==parent.Id);Assert.Equal(parent.Revision+1,nowParent.Revision);Assert.Equal(parent.Envelope,nowParent.Envelope);Assert.Equal(parent.EditedAt,nowParent.EditedAt);Assert.Equal(other,Bytes(await db.Records.AsNoTracking().SingleAsync(x=>x.Id==a.Record.Id)));
            var fs=JsonSerializer.Deserialize<FolderAssociationSnapshot>((await db.TrashEntries.SingleAsync(x=>x.ResourceKind=="folder"&&x.ResourceId==leaf.PublicId)).AssociationSnapshot,ProtectionFixture.Json)!;Assert.Equal(child.PublicId,fs.ParentFolderId);Assert.Equal(new[]{inactive.PublicId},fs.ProfileIds);Assert.Equal(new[]{a.Collection.PublicId},fs.CollectionIds);
            var rs=JsonSerializer.Deserialize<RecordAssociationSnapshot>((await db.TrashEntries.SingleAsync(x=>x.ResourceKind=="record"&&x.ResourceId==r2.PublicId)).AssociationSnapshot,ProtectionFixture.Json)!;Assert.Equal(leaf.PublicId,rs.FolderId);Assert.Equal(new[]{p.PublicId,inactive.PublicId}.Order(),rs.ProfileIds);Assert.Equal(new[]{a.Collection.PublicId,b.Collection.PublicId}.Order(),rs.CollectionIds);
            Assert.True(await db.CollectionGrants.AnyAsync(x=>x.CollectionId==a.Collection.Id&&x.State==CollectionGrantState.Active));
        }
        Assert.Equal(recipientBefore,await Snapshot(recipient));Assert.Equal("not_found",(await new FolderReadStore(fixture).ReadAsync(new(recipient.Actor,recipient.Verifier,leaf.PublicId),default)).Error);Assert.Equal("not_found",(await new RecordReadStore(fixture).ReadAsync(new(recipient.Actor,recipient.Verifier,r2.PublicId),default)).Error);
    }
    [FunctionalFact]
    public async Task GivenActualIndependentRecordAndFolderTrash_WhenLaterTrashingRoot_ThenPreserveEarlierOperationsAndDeadlines()
    {
        using var owner=new ProtectionFixture();var s=await ProfileSetup.Create(fixture,owner);var root=await Folder(s);var independent=await Folder(s,root.Id);var previousRecord=await Record(s,root.Id);var previousChildRecord=await Record(s,independent.Id);var child=await Folder(s,root.Id);var activeRecord=await Record(s,child.Id);
        var first=await new RecordTrashStore(fixture).TrashAsync(new(s.Actor,s.Verifier,previousRecord.PublicId,1),default);Assert.Null(first.Error);var second=await Trash(s,independent);await Success(s,independent,[independent],[previousChildRecord],second);root=await Row(root.Id);var oldFolder=Bytes(await Row(independent.Id));var oldRecord=Bytes(await RecordRow(previousRecord.Id));var oldChildRecord=Bytes(await RecordRow(previousChildRecord.Id));
        await using var db=fixture.CreateContext();var oldOps=Bytes(await db.TrashOperations.AsNoTracking().Where(x=>x.AccountId==s.InternalId).OrderBy(x=>x.Id).ToArrayAsync());var oldEntries=Bytes(await db.TrashEntries.AsNoTracking().Where(x=>x.ResourceId==previousRecord.PublicId||x.ResourceId==independent.PublicId||x.ResourceId==previousChildRecord.PublicId).OrderBy(x=>x.Id).ToArrayAsync());await Success(s,root,[root,child],[activeRecord],await Trash(s,root,root.Revision));
        Assert.Equal(oldFolder,Bytes(await Row(independent.Id)));Assert.Equal(oldRecord,Bytes(await RecordRow(previousRecord.Id)));Assert.Equal(oldChildRecord,Bytes(await RecordRow(previousChildRecord.Id)));Assert.Equal(oldEntries,Bytes(await db.TrashEntries.AsNoTracking().Where(x=>x.ResourceId==previousRecord.PublicId||x.ResourceId==independent.PublicId||x.ResourceId==previousChildRecord.PublicId).OrderBy(x=>x.Id).ToArrayAsync()));Assert.Equal(oldOps,Bytes(await db.TrashOperations.AsNoTracking().Where(x=>x.PublicId==first.Data!.TrashOperationId||x.PublicId==second.Data!.TrashOperationId).OrderBy(x=>x.Id).ToArrayAsync()));
    }
