    public async Task GivenCorruptOrConflictingCascadeMember_WhenTrashing_ThenNoPartialOperation(string member,string kind,string error)
    {
        using var owner=new ProtectionFixture();var s=await ProfileSetup.Create(fixture,owner);var root=await Folder(s);var child=await Folder(s,root.Id);var record=await Record(s,child.Id);var id=member=="folder"?root.PublicId:member=="child"?child.PublicId:record.PublicId;await using(var db=fixture.CreateContext()){
            if(member=="record"){var r=await db.Records.SingleAsync(x=>x.Id==record.Id);if(kind=="zeroRevision")r.Revision=0;if(kind=="zeroSequence")r.ServerSequence=0;if(kind=="maxRevision")r.Revision=ProtocolBinary.MaxInteger;if(kind=="purge")r.PurgeAt=DateTimeOffset.UtcNow.AddDays(30);}
            else{var f=await db.Folders.SingleAsync(x=>x.PublicId==id);if(kind=="zeroRevision")f.Revision=0;if(kind=="zeroSequence")f.ServerSequence=0;if(kind=="unsafeSequence")f.ServerSequence=ProtocolBinary.MaxInteger+1;if(kind=="maxRevision")f.Revision=ProtocolBinary.MaxInteger;if(kind=="purge")f.PurgeAt=DateTimeOffset.UtcNow.AddDays(30);}
            if(kind=="oldEntry"){var op=new TrashOperation{AccountId=s.InternalId,RootResourceKind=member=="record"?"record":"folder",RootResourceId=id,DeletedAt=DateTimeOffset.UtcNow,PurgeAt=DateTimeOffset.UtcNow.AddDays(30)};db.TrashOperations.Add(op);await db.SaveChangesAsync();db.TrashEntries.Add(new(){OperationId=op.Id,ResourceKind=op.RootResourceKind,ResourceId=id,AssociationSnapshot="{}"u8.ToArray()});}await db.SaveChangesAsync();}
        var before=await Snapshot(s);Assert.Equal(error,(await Trash(s,root,member=="folder"&&kind=="maxRevision"?ProtocolBinary.MaxInteger:1)).Error);Assert.Equal(before,await Snapshot(s));
    }
