    {using var owner=new ProtectionFixture();var s=await ProfileSetup.Create(fixture,owner);var root=await Folder(s);var record=await Record(s,root.Id);await using(var db=fixture.CreateContext()){if(kind=="folder")await db.Folders.Where(x=>x.Id==root.Id).ExecuteUpdateAsync(x=>x.SetProperty(v=>v.EditedAt,DateTimeOffset.MinValue));else await db.Records.Where(x=>x.Id==record.Id).ExecuteUpdateAsync(x=>x.SetProperty(v=>v.EditedAt,DateTimeOffset.MinValue));}var before=await Snapshot(s);Assert.Equal("persistence_unavailable",(await Trash(s,root)).Error);Assert.Equal(before,await Snapshot(s));}
    [FunctionalTheory][InlineData("folder")][InlineData("record")]
    public async Task GivenTypedTerminalDescendant_WhenTrashingRoot_ThenExcludeTerminalBranchWithoutChangingRetainedRows(string kind)
    {
        using var owner=new ProtectionFixture();var s=await ProfileSetup.Create(fixture,owner);var root=await Folder(s);var child=await Folder(s,root.Id);var record=await Record(s,child.Id);var active=await Record(s,root.Id);await using(var db=fixture.CreateContext()){db.TerminalErasures.Add(new(){ResourceKind=kind,ResourceId=kind=="folder"?child.PublicId:record.PublicId,DeletedAt=DateTimeOffset.UtcNow});await db.SaveChangesAsync();}var previousChild=Bytes(await Row(child.Id));var previousRecord=Bytes(await RecordRow(record.Id));await Success(s,root,kind=="folder"?[root]:[root,child],[active],await Trash(s,root));Assert.Equal(previousRecord,Bytes(await RecordRow(record.Id)));if(kind=="folder")Assert.Equal(previousChild,Bytes(await Row(child.Id)));
    }
    [FunctionalTheory][InlineData("parent")][InlineData("sibling")]
