    [FunctionalFact]
    public async Task GivenActualOwnerRotationWaitsForCascadeAccount_WhenTrashCommits_ThenStaleInventoryConflictsAndProofSurvives()
    {
        using var owner=new ProtectionFixture();var s=await ProfileSetup.Create(fixture,owner);var root=await Folder(s);var child=await Folder(s,root.Id);var record=await Record(s,child.Id);var change=new ProtectionChange(s.AccountId,1,1,"rotate-content",owner.Rewrap(),[new("account",s.AccountId,1,ProfileSetup.Envelope(2)),new("folder",root.PublicId,1,ProfileSetup.Envelope(2)),new("folder",child.PublicId,1,ProfileSetup.Envelope(2)),new("record",record.PublicId,1,ProfileSetup.Envelope(2))]);var raw=Bytes(change);var challenge=(await new VaultProtectionStore(fixture).ChallengeAsync(s.Actor,"change-protection",ProtocolBinary.Encode(SHA256.HashData(raw)),default)).Data!;
        var reached=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var release=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var blocked=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);using var ct=new CancellationTokenSource(TimeSpan.FromSeconds(25));var trash=new FolderTrashStore(new ProfileSetup.Factory(fixture,new BeforeContent(async()=>{reached.TrySetResult();await release.Task.WaitAsync(ct.Token);}))).TrashAsync(new(s.Actor,s.Verifier,root.PublicId,1),ct.Token);await reached.Task.WaitAsync(TimeSpan.FromSeconds(10));var rotation=new VaultProtectionChangeStore(new ProfileSetup.Factory(fixture,new Signal(blocked,"account"))).ChangeAsync(new(s.Actor,s.Verifier,challenge.ChallengeId,owner.Sign(challenge),raw,change),ct.Token);try{await blocked.Task.WaitAsync(TimeSpan.FromSeconds(10));Assert.False(rotation.IsCompleted);}finally{release.TrySetResult();}await Success(s,root,[root,child],[record],await trash);Assert.Equal("revision_conflict",(await rotation).Error);await using var db=fixture.CreateContext();Assert.False((await db.VaultUnlockChallenges.SingleAsync(x=>x.PublicId==challenge.ChallengeId)).Consumed);Assert.Equal(1,(await db.VaultProtections.SingleAsync(x=>x.AccountId==s.InternalId)).Revision);
    }
    [FunctionalFact]
    public async Task GivenDeepUnrelatedInventories_WhenTrashingSmallSubtree_ThenBoundedRootAndOnlyCapturedStructuralLocks()
    {
        using var owner=new ProtectionFixture();using var client=new ProtectionFixture();var s=await ProfileSetup.Create(fixture,owner);var foreign=await ProfileSetup.Create(fixture,client);var upper=await Folder(s);var parent=await Folder(s,upper.Id);var root=await Folder(s,parent.Id);var child=await Folder(s,root.Id);var record=await Record(s,child.Id);foreach(var state in new[]{s,foreign}){long? previous=null;for(var i=0;i<50;i++){var f=await Folder(state,previous);previous=f.Id;}for(var i=0;i<50;i++)await Folder(state);}
        var capture=new Capture(fixture);await Success(s,root,[root,child],[record],await new FolderTrashStore(new ProfileSetup.Factory(fixture,capture)).TrashAsync(new(s.Actor,s.Verifier,root.PublicId,1),default));Assert.NotNull(capture.Plan);using var doc=JsonDocument.Parse(capture.Plan!);var nodes=Nodes(doc.RootElement[0].GetProperty("Plan")).ToArray();Assert.Equal(1d,Assert.Single(nodes,x=>x.TryGetProperty("Subplan Name",out var n)&&n.GetString()=="CTE candidates").GetProperty("Actual Rows").GetDouble());Assert.Equal(3d,Assert.Single(nodes,x=>x.TryGetProperty("Subplan Name",out var n)&&n.GetString()=="CTE ancestry").GetProperty("Actual Rows").GetDouble());Assert.Single(capture.Locks,x=>x.Contains("FROM cerberus.account"));Assert.DoesNotContain(capture.Locks,x=>x.Contains("cerberus.collection_grant"));var folders=Assert.Single(capture.Locks,x=>x.Contains("FROM cerberus.folder")&&x.Contains("FOR UPDATE"));Assert.Contains("ORDER BY",folders);Assert.Equal(new[]{parent.Id,root.Id,child.Id}.Order(),Assert.Single(capture.FolderLockIds).Order());Assert.Single(capture.Locks,x=>x.Contains("FROM cerberus.record")&&x.Contains("FOR UPDATE"));Assert.Null((await Row(upper.Id)).DeletedAt);Assert.Equal(upper.Revision,(await Row(upper.Id)).Revision);
    }
    private static IEnumerable<JsonElement> Nodes(JsonElement node){yield return node;if(node.TryGetProperty("Plans",out var children))foreach(var c in children.EnumerateArray())foreach(var n in Nodes(c))yield return n;}
    private sealed class Capture(PostgresFixture fixture):DbCommandInterceptor
    {
        public List<string> Locks{get;}=[];public List<long[]> FolderLockIds{get;}=[];public string? Plan{get;private set;}
        private void Note(DbCommand c){if(c.CommandText.Contains("FROM cerberus.folder")&&c.CommandText.Contains("FOR UPDATE"))FolderLockIds.Add(c.Parameters.Cast<NpgsqlParameter>().Select(x=>x.Value).OfType<long[]>().Single());if(c.CommandText.Contains("FOR UPDATE")||c.CommandText.Contains("FOR NO KEY UPDATE")||c.CommandText.Contains("FOR SHARE"))Locks.Add(c.CommandText);}
        public override ValueTask<InterceptionResult<int>> NonQueryExecutingAsync(DbCommand c,CommandEventData d,InterceptionResult<int> r,CancellationToken ct=default){Note(c);return ValueTask.FromResult(r);}
        public override async ValueTask<InterceptionResult<DbDataReader>> ReaderExecutingAsync(DbCommand c,CommandEventData d,InterceptionResult<DbDataReader> r,CancellationToken ct=default){Note(c);if(Plan is null&&c.CommandText.StartsWith("WITH RECURSIVE")){await using var db=fixture.CreateContext();await db.Database.OpenConnectionAsync(ct);await using var cmd=db.Database.GetDbConnection().CreateCommand();cmd.CommandText="EXPLAIN (ANALYZE, FORMAT JSON) "+c.CommandText;foreach(var p in c.Parameters.Cast<NpgsqlParameter>())cmd.Parameters.Add(p.Clone());Plan=(string)(await cmd.ExecuteScalarAsync(ct))!;await System.IO.File.WriteAllTextAsync("/tmp/cerberus-uc27-explain.json",Plan,ct);}return r;}
    }

    private FolderTrashStore Store()=>new(fixture);
    private Task<VaultResult<FolderTrashDetails>> Trash(ProfileSetup.State s,VaultFolder folder,long revision=1)=>Store().TrashAsync(new(s.Actor,s.Verifier,folder.PublicId,revision),default);
    private async Task<Profile> ProfileRow(long id){await using var db=fixture.CreateContext();return await db.Profiles.AsNoTracking().SingleAsync(x=>x.Id==id);}
    private async Task<VaultRecord> RecordRow(long id){await using var db=fixture.CreateContext();return await db.Records.AsNoTracking().SingleAsync(x=>x.Id==id);}
    private async Task Success(ProfileSetup.State s,VaultFolder original,VaultFolder[] folders,VaultRecord[] records,VaultResult<FolderTrashDetails> result)
    {
        Assert.Null(result.Error);var d=result.Data!;Assert.Equal(original.PublicId,d.FolderId);Assert.NotEqual(Guid.Empty,d.TrashOperationId);Assert.Equal(original.Revision+1,d.Revision);Assert.True(d.ServerSequence>original.ServerSequence);Assert.InRange(d.ServerSequence,1,ProtocolBinary.MaxInteger);Assert.Equal(TimeSpan.Zero,d.DeletedAt.Offset);Assert.Equal(0,d.DeletedAt.Ticks%10);Assert.Equal(TimeSpan.FromDays(30),d.PurgeAt-d.DeletedAt);Assert.Equal(TimeSpan.Zero,d.PurgeAt.Offset);
        await using var db=fixture.CreateContext();var op=await db.TrashOperations.AsNoTracking().SingleAsync(x=>x.PublicId==d.TrashOperationId);Assert.Equal("folder",op.RootResourceKind);Assert.Equal(s.InternalId,op.AccountId);Assert.Equal(original.PublicId,op.RootResourceId);Assert.Equal(d.DeletedAt,op.DeletedAt);Assert.Equal(d.PurgeAt,op.PurgeAt);var entries=await db.TrashEntries.AsNoTracking().Where(x=>x.OperationId==op.Id).ToListAsync();Assert.Equal(folders.Length+records.Length,entries.Count);Assert.Equal(folders.Select(x=>x.PublicId).Order(),entries.Where(x=>x.ResourceKind=="folder").Select(x=>x.ResourceId).Order());Assert.Equal(records.Select(x=>x.PublicId).Order(),entries.Where(x=>x.ResourceKind=="record").Select(x=>x.ResourceId).Order());var q=Assert.Single(await db.RetentionWorkItems.AsNoTracking().Where(x=>x.OperationKey=="trash/"+op.PublicId).ToListAsync());Assert.Equal(d.PurgeAt,q.DueAt);Assert.Null(q.CompletedAt);
        foreach(var f in folders){var row=await db.Folders.AsNoTracking().SingleAsync(x=>x.Id==f.Id);Assert.Equal(f.Envelope,row.Envelope);Assert.Equal(f.EditedAt,row.EditedAt);Assert.Equal(f.AccountId,row.AccountId);Assert.Null(row.ParentFolderId);Assert.Equal(f.Revision+1,row.Revision);Assert.True(row.ServerSequence>f.ServerSequence);Assert.InRange(row.ServerSequence,1,ProtocolBinary.MaxInteger);Assert.Equal(d.DeletedAt,row.DeletedAt);Assert.Equal(d.PurgeAt,row.PurgeAt);Assert.NotEqual(f.ConcurrencyStamp,row.ConcurrencyStamp);Assert.False(await db.ProfileFolders.AnyAsync(x=>x.FolderId==f.Id));Assert.False(await db.CollectionFolders.AnyAsync(x=>x.FolderId==f.Id));}
        foreach(var r in records){var row=await db.Records.AsNoTracking().SingleAsync(x=>x.Id==r.Id);Assert.Equal(r.Envelope,row.Envelope);Assert.Equal(r.EditedAt,row.EditedAt);Assert.Equal(r.AccountId,row.AccountId);Assert.Null(row.FolderId);Assert.Equal(r.Revision+1,row.Revision);Assert.True(row.ServerSequence>r.ServerSequence);Assert.InRange(row.ServerSequence,1,ProtocolBinary.MaxInteger);Assert.Equal(d.DeletedAt,row.DeletedAt);Assert.Equal(d.PurgeAt,row.PurgeAt);Assert.NotEqual(r.ConcurrencyStamp,row.ConcurrencyStamp);Assert.False(await db.ProfileRecords.AnyAsync(x=>x.RecordId==r.Id));Assert.False(await db.CollectionRecords.AnyAsync(x=>x.RecordId==r.Id));}
    }

    private async Task<VaultFolder> Row(long id){await using var db=fixture.CreateContext();return await db.Folders.AsNoTracking().SingleAsync(x=>x.Id==id);}
    private async Task<VaultRecord> Record(ProfileSetup.State s,long? folder=null){var row=new VaultRecord{PublicId=Guid.NewGuid(),AccountId=s.InternalId,FolderId=folder,Envelope=Bytes(ProfileSetup.Envelope()),EditedAt=DateTimeOffset.UnixEpoch};await using var db=fixture.CreateContext();db.Records.Add(row);await db.SaveChangesAsync();return row;}
    private async Task<VaultFolder> Folder(ProfileSetup.State s,long? parent=null){var row=new VaultFolder{PublicId=Guid.NewGuid(),AccountId=s.InternalId,ParentFolderId=parent,Envelope=Bytes(ProfileSetup.Envelope()),EditedAt=DateTimeOffset.UnixEpoch};await using var db=fixture.CreateContext();db.Folders.Add(row);await db.SaveChangesAsync();return row;}
    private async Task<Profile> Profile(ProfileSetup.State s,ProtectionFixture owner,ProtectionFixture scoped,Guid[]? records=null,Guid[]? folders=null,Guid[]? collections=null){var input=ProfileSetup.Input(s,owner,scoped) with{RecordIds=records??[],FolderIds=folders??[],CollectionIds=collections??[]};Assert.Null((await new ProfileCreateStore(fixture).CreateAsync(new(s.Actor,s.Verifier,input),default)).Error);await using var db=fixture.CreateContext();return await db.Profiles.AsNoTracking().SingleAsync(x=>x.PublicId==input.ProfileId);}
    private async Task Members(ProfileSetup.State s,VaultCollection collection,long[] records,long[] folders){await using var db=fixture.CreateContext();db.CollectionRecords.AddRange(records.Select(x=>new CollectionRecord{AccountId=s.InternalId,CollectionId=collection.Id,RecordId=x}));db.CollectionFolders.AddRange(folders.Select(x=>new CollectionFolder{AccountId=s.InternalId,CollectionId=collection.Id,FolderId=x}));await db.SaveChangesAsync();}
    private async Task<string> Selected(ProfileSetup.State s,long profile){var verifier=Convert.ToHexStringLower(RandomNumberGenerator.GetBytes(32));await using var db=fixture.CreateContext();db.VaultAccessSessions.Add(new(){AccountId=s.InternalId,ProfileId=profile,HandleVerifier=verifier,IssuedAt=DateTimeOffset.UtcNow.AddMinutes(-1),ExpiresAt=DateTimeOffset.UtcNow.AddHours(1),PolicyRevision=1,RevocationGeneration=1});await db.SaveChangesAsync();return verifier;}
    private static byte[] Bytes<T>(T value)=>JsonSerializer.SerializeToUtf8Bytes(value,ProtectionFixture.Json);
    private async Task<string> Snapshot(ProfileSetup.State s){await using var db=fixture.CreateContext();return JsonSerializer.Serialize(new{Account=await db.Accounts.AsNoTracking().SingleAsync(x=>x.Id==s.InternalId),Protection=await db.VaultProtections.AsNoTracking().SingleOrDefaultAsync(x=>x.AccountId==s.InternalId),Sessions=await db.VaultAccessSessions.AsNoTracking().Where(x=>x.AccountId==s.InternalId).OrderBy(x=>x.Id).ToArrayAsync(),Records=await db.Records.AsNoTracking().Where(x=>x.AccountId==s.InternalId).OrderBy(x=>x.Id).ToArrayAsync(),Folders=await db.Folders.AsNoTracking().Where(x=>x.AccountId==s.InternalId).OrderBy(x=>x.Id).ToArrayAsync(),Collections=await db.Collections.AsNoTracking().Where(x=>x.AccountId==s.InternalId).OrderBy(x=>x.Id).ToArrayAsync(),Profiles=await db.Profiles.AsNoTracking().Where(x=>x.AccountId==s.InternalId).OrderBy(x=>x.Id).ToArrayAsync(),ProfileRecords=await db.ProfileRecords.AsNoTracking().Where(x=>x.AccountId==s.InternalId).OrderBy(x=>x.ProfileId).ThenBy(x=>x.RecordId).ToArrayAsync(),ProfileFolders=await db.ProfileFolders.AsNoTracking().Where(x=>x.AccountId==s.InternalId).OrderBy(x=>x.ProfileId).ThenBy(x=>x.FolderId).ToArrayAsync(),ProfileCollections=await db.ProfileCollections.AsNoTracking().Where(x=>db.Profiles.Any(p=>p.Id==x.ProfileId && p.AccountId==s.InternalId)).OrderBy(x=>x.ProfileId).ThenBy(x=>x.CollectionId).ToArrayAsync(),CollectionRecords=await db.CollectionRecords.AsNoTracking().Where(x=>x.AccountId==s.InternalId).OrderBy(x=>x.CollectionId).ThenBy(x=>x.RecordId).ToArrayAsync(),CollectionFolders=await db.CollectionFolders.AsNoTracking().Where(x=>x.AccountId==s.InternalId).OrderBy(x=>x.CollectionId).ThenBy(x=>x.FolderId).ToArrayAsync(),Operations=await db.TrashOperations.AsNoTracking().Where(x=>x.AccountId==s.InternalId).OrderBy(x=>x.Id).ToArrayAsync(),Entries=await db.TrashEntries.AsNoTracking().Where(x=>db.TrashOperations.Any(o=>o.Id==x.OperationId&&o.AccountId==s.InternalId)).OrderBy(x=>x.Id).ToArrayAsync(),Queue=await db.RetentionWorkItems.AsNoTracking().Where(x=>db.TrashOperations.Any(o=>o.AccountId==s.InternalId&&x.OperationKey=="trash/"+o.PublicId)).OrderBy(x=>x.Id).ToArrayAsync(),Grants=await db.CollectionGrants.AsNoTracking().Where(x=>x.RecipientAccountId==s.InternalId || db.Collections.Any(c=>c.Id==x.CollectionId && c.AccountId==s.InternalId)).OrderBy(x=>x.Id).ToArrayAsync()});}

